const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const furnaceCreek = ee.Geometry.Point([-116.8675, 36.4574]);
  const targetDate = '2013-06-30';

  console.log('Analyzing air temperature at Furnace Creek on June 30, 2013...');

  // 2. Data Acquisition & Check
  // ERA5-Land hourly data for air temperature at 2m
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(targetDate, '2013-07-01')
    .select('temperature_2m');

  const imageCount = era5.size().getInfo();
  console.log(`ERA5 images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log('No ERA5 data available for this date.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get maximum temperature across all hours
  const maxTemp = era5.max();

  // 4. Calculation
  const result = maxTemp.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: furnaceCreek,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const tempKelvin = result.temperature_2m;

  // Check for valid data
  if (tempKelvin === null || tempKelvin === undefined) {
    console.log('Temperature calculation returned null.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert Kelvin to Celsius
  const tempCelsius = tempKelvin - 273.15;

  // 5. Validation & Final Answer
  console.log(`Maximum temperature: ${tempCelsius.toFixed(2)}°C (${tempKelvin.toFixed(2)}K)`);

  // Check if temperature is in reasonable range
  if (tempCelsius < -100 || tempCelsius > 100) {
    console.log('Temperature value out of reasonable range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if temperature reached over 50°C
  if (tempCelsius >= 50.0) {
    console.log('Temperature exceeded 50°C.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Temperature did not reach 50°C.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
